<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/mailer.php';$token=trim($_GET['token']??$_POST['token']??'');$stmt=db()->prepare('SELECT pr.*,u.full_name,u.email FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() LIMIT 1');$stmt->execute([hash('sha256',$token)]);$reset=$stmt->fetch();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if(!$reset)$error='This reset link is invalid or expired.';elseif(strlen($password)<8||$password!==$confirm)$error='Use matching passwords with at least 8 characters.';else{$old=db()->prepare('SELECT password_hash FROM password_history WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$old->execute([$reset['user_id']]);foreach($old as $row)if(password_verify($password,$row['password_hash']))$error='You cannot reuse one of your five recent passwords.';if(!$error){$pdo=db();$pdo->prepare('INSERT INTO password_history (user_id,password_hash) SELECT id,password_hash FROM users WHERE id=?')->execute([$reset['user_id']]);$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$reset['user_id']]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$reset['id']]);audit_action('password_reset_completed','users',(int)$reset['user_id']);send_notification($reset['email'],'Your Barangay password was changed','<p>Your password was changed successfully. If this was not you, contact the administrator immediately.</p>');flash('success','Password reset complete. Sign in with your new password.');redirect('login.php');}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reset password · Barangay Information System</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><div class="eyebrow">Account recovery</div><h1>Choose a new password.</h1><?php if($error): ?><div class="flash error"><?= h($error) ?></div><?php endif; ?><form method="post" class="login-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="token" value="<?= h($token) ?>"><label>New password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirm_password" minlength="8" required autocomplete="new-password"></label><button class="primary-button full-button">Save new password</button></form></div></body></html>
